Please explain what this Go package for our veterinary practice does, review it for bugs and design problems, and write table-driven tests for it. I'd like the tests to cover the edge cases, not just the happy path.

```go
package dosage

import (
	"errors"
	"fmt"
	"math"
	"strings"
)

type Species string

const (
	Dog    Species = "dog"
	Cat    Species = "cat"
	Rabbit Species = "rabbit"
)

type Drug struct {
	Name        string
	MgPerKg     float64
	MaxDailyMg  float64
	DosesPerDay int
	Species     []Species
}

type Patient struct {
	Name     string
	Species  Species
	WeightKg float64
	Allergy  []string
}

type Prescription struct {
	Drug       string
	DoseMg     float64
	DosesDaily int
	Warning    string
}

var ErrWeight = errors.New("weight must be positive")
var ErrSpecies = errors.New("drug not approved for species")

var catalog = map[string]Drug{
	"amoxicillin": {"amoxicillin", 12.5, 500, 2, []Species{Dog, Cat}},
	"meloxicam":   {"meloxicam", 0.1, 5, 1, []Species{Dog}},
	"metacam-rab": {"metacam-rab", 0.3, 3, 1, []Species{Rabbit}},
}

func approved(d Drug, s Species) bool {
	for _, x := range d.Species {
		if x == s {
			return true
		}
	}
	return false
}

func allergic(p Patient, drug string) bool {
	for _, a := range p.Allergy {
		if strings.ToLower(a) == strings.ToLower(drug) {
			return true
		}
	}
	return false
}

func round(v float64, places int) float64 {
	f := math.Pow(10, float64(places))
	return math.Round(v*f) / f
}

func Calculate(p Patient, drugName string) (Prescription, error) {
	if p.WeightKg <= 0 {
		return Prescription{}, ErrWeight
	}
	d, ok := catalog[strings.ToLower(drugName)]
	if !ok {
		return Prescription{}, fmt.Errorf("unknown drug %q", drugName)
	}
	if !approved(d, p.Species) {
		return Prescription{}, ErrSpecies
	}
	dose := round(d.MgPerKg*p.WeightKg, 1)
	daily := dose * float64(d.DosesPerDay)
	rx := Prescription{Drug: d.Name, DoseMg: dose, DosesDaily: d.DosesPerDay}
	if daily > d.MaxDailyMg {
		dose = round(d.MaxDailyMg/float64(d.DosesPerDay), 1)
		rx.DoseMg = dose
		rx.Warning = "dose capped at daily maximum"
	}
	if allergic(p, d.Name) {
		rx.Warning = "patient has recorded allergy"
	}
	return rx, nil
}
```

Some context. The reception team prints the Calculate result on the treatment sheet, and the vets have told us they trust the numbers. We have had one near miss where a rabbit owner was handed a dog dose, so please be strict about anything that could produce an unsafe number. The catalog will later move to a database, so tell me whether the current design makes that change harder.

I inherited this TypeScript module from a contractor who built the plant inventory for our botanical garden. Please explain what each part does, propose a refactoring that would make it easier to maintain, and write tests for the refactored version.

```ts
export type Zone = "tropical" | "alpine" | "desert" | "woodland";

export interface Specimen {
  id: string;
  latinName: string;
  commonName?: string;
  zone: Zone;
  acquired: string; // ISO date
  bed: string;
  health: number; // 0 to 100
  lastWatered?: string;
}

export interface WateringRule {
  zone: Zone;
  everyDays: number;
}

const rules: WateringRule[] = [
  { zone: "tropical", everyDays: 2 },
  { zone: "alpine", everyDays: 5 },
  { zone: "desert", everyDays: 21 },
  { zone: "woodland", everyDays: 7 },
];

const inventory: Specimen[] = [];

export function addSpecimen(s: Specimen): void {
  for (const x of inventory) {
    if (x.id === s.id) {
      throw new Error("duplicate id " + s.id);
    }
  }
  if (s.health < 0 || s.health > 100) {
    throw new Error("health out of range");
  }
  inventory.push(s);
}

export function findByZone(zone: Zone): Specimen[] {
  return inventory.filter((s) => s.zone === zone);
}

export function search(term: string): Specimen[] {
  const t = term.toLowerCase();
  return inventory.filter(
    (s) =>
      s.latinName.toLowerCase().includes(t) ||
      (s.commonName !== undefined && s.commonName.toLowerCase().includes(t))
  );
}

function daysBetween(a: string, b: string): number {
  const ms = new Date(b).getTime() - new Date(a).getTime();
  return Math.floor(ms / 86400000);
}

export function dueForWatering(today: string): Specimen[] {
  const out: Specimen[] = [];
  for (const s of inventory) {
    const rule = rules.find((r) => r.zone === s.zone);
    if (!rule) continue;
    const since = s.lastWatered ?? s.acquired;
    if (daysBetween(since, today) >= rule.everyDays) {
      out.push(s);
    }
  }
  return out;
}

export function markWatered(id: string, date: string): void {
  const s = inventory.find((x) => x.id === id);
  if (!s) throw new Error("not found: " + id);
  s.lastWatered = date;
}

export function updateHealth(id: string, health: number): Specimen {
  const s = inventory.find((x) => x.id === id);
  if (!s) throw new Error("not found: " + id);
  s.health = health;
  return s;
}

export function atRisk(threshold = 40): string[] {
  return inventory
    .filter((s) => s.health < threshold)
    .sort((a, b) => a.health - b.health)
    .map((s) => `${s.commonName ?? s.latinName} (${s.bed}): ${s.health}`);
}
```

Things I already worry about: the global inventory array makes testing painful, updateHealth does no validation although addSpecimen does, dates are plain strings, and the volunteers who use dueForWatering() on Monday mornings sometimes get specimens listed that were watered the same day. I also expect we will add a greenhouse module soon that needs the same watering logic with different rules, so keep that in mind.

Here is a Python module we use at our recycling plant to track bales leaving the sorting hall. Please do a thorough code review, covering bugs, edge cases, style and design, and then write a full set of unit tests with pytest.

```python
import datetime
from dataclasses import dataclass, field

MATERIALS = ["paper", "glass", "metal", "plastic"]
PRICE_PER_TONNE = {"paper": 85.0, "glass": 30.0, "metal": 310.0, "plastic": 140.0}
MAX_CONTAMINATION = 0.08


@dataclass
class Bale:
    bale_id: str
    material: str
    weight_kg: float
    contamination: float
    sorted_on: datetime.date
    shipped: bool = False
    notes: list = field(default_factory=list)


class BaleLedger:
    def __init__(self):
        self.bales = {}

    def add(self, bale):
        if bale.material not in MATERIALS:
            raise ValueError("unknown material: " + bale.material)
        if bale.weight_kg < 0:
            raise ValueError("negative weight")
        if bale.bale_id in self.bales:
            raise KeyError("duplicate bale " + bale.bale_id)
        self.bales[bale.bale_id] = bale

    def is_sellable(self, bale_id):
        b = self.bales[bale_id]
        return b.contamination <= MAX_CONTAMINATION and not b.shipped

    def value(self, bale_id):
        b = self.bales[bale_id]
        tonnes = b.weight_kg / 1000
        price = PRICE_PER_TONNE[b.material]
        if b.contamination > 0.04:
            price = price * 0.9
        return round(tonnes * price, 2)

    def ship(self, bale_ids, date=None):
        date = date or datetime.date.today()
        total = 0
        for bid in bale_ids:
            if not self.is_sellable(bid):
                raise ValueError("bale not sellable: " + bid)
            self.bales[bid].shipped = True
            self.bales[bid].notes.append("shipped " + str(date))
            total += self.value(bid)
        return total

    def stock_by_material(self):
        result = {}
        for b in self.bales.values():
            if not b.shipped:
                result[b.material] = result.get(b.material, 0) + b.weight_kg
        return result

    def oldest_unshipped(self, n=5):
        items = [b for b in self.bales.values() if not b.shipped]
        items.sort(key=lambda b: b.sorted_on)
        return items[:n]

    def average_contamination(self, material):
        items = [b for b in self.bales.values() if b.material == material]
        return sum(b.contamination for b in items) / len(items)
```

Some background: the ledger holds around 1,500 bales at any time, the shipping clerks call ship() with a list of up to 40 bales for each lorry, and they have complained that a lorry load sometimes fails halfway and then the system says some bales are shipped when no lorry left. The finance team also asked why the value of a bale changes depending on the contamination rate in a way they cannot reproduce by hand.

I inherited this module from a colleague who left the county records office, and nobody can tell me why it works the way it does. Could you explain each part in turn, propose a refactoring that makes the request-handling logic easier to maintain, and write tests for the refactored version?

```ts
// requestQueue.ts - handles public records requests for the Halvern County Archive

export type RequestStatus = "received" | "searching" | "review" | "fulfilled" | "denied";

export interface RecordsRequest {
  id: string;
  requester: string;
  email: string;
  description: string;
  receivedAt: Date;
  dueAt: Date;
  status: RequestStatus;
  pageCount: number;
  feeCents: number;
  exemptions: string[];
}

const LEGAL_DAYS = 10;
const FREE_PAGES = 25;
const COST_PER_PAGE_CENTS = 15;
const HOLIDAYS = ["2026-11-26", "2026-12-25", "2027-01-01"];

function isBusinessDay(d: Date): boolean {
  const day = d.getDay();
  if (day === 0 || day === 6) return false;
  const iso = d.toISOString().slice(0, 10);
  return !HOLIDAYS.includes(iso);
}

export function computeDueDate(received: Date): Date {
  const due = new Date(received.getTime());
  let counted = 0;
  while (counted < LEGAL_DAYS) {
    due.setDate(due.getDate() + 1);
    if (isBusinessDay(due)) counted++;
  }
  return due;
}

export function computeFee(pageCount: number, requesterIsPress: boolean): number {
  if (requesterIsPress) return 0;
  const billable = pageCount - FREE_PAGES;
  if (billable <= 0) return 0;
  return billable * COST_PER_PAGE_CENTS;
}

export class RequestQueue {
  private items: Map<string, RecordsRequest> = new Map();
  private counter = 0;

  create(requester: string, email: string, description: string, now: Date = new Date()): RecordsRequest {
    if (!email.includes("@")) {
      throw new Error("invalid email");
    }
    if (description.trim().length < 10) {
      throw new Error("description too short");
    }
    this.counter++;
    const id = "HCA-" + now.getFullYear() + "-" + String(this.counter).padStart(4, "0");
    const req: RecordsRequest = {
      id,
      requester,
      email,
      description,
      receivedAt: now,
      dueAt: computeDueDate(now),
      status: "received",
      pageCount: 0,
      feeCents: 0,
      exemptions: [],
    };
    this.items.set(id, req);
    return req;
  }

  get(id: string): RecordsRequest | undefined {
    return this.items.get(id);
  }

  advance(id: string, next: RequestStatus): RecordsRequest {
    const req = this.items.get(id);
    if (!req) throw new Error("no such request: " + id);
    if (req.status === "fulfilled" || req.status === "denied") {
      throw new Error("request already closed");
    }
    if (next === "searching" && req.status !== "received") {
      throw new Error("can only search a received request");
    }
    if (next === "review" && req.status !== "searching") {
      throw new Error("can only review after searching");
    }
    if (next === "fulfilled" && req.status !== "review") {
      throw new Error("must be reviewed before fulfilment");
    }
    req.status = next;
    return req;
  }

  recordSearchResult(id: string, pageCount: number, press = false): void {
    const req = this.items.get(id);
    if (!req) throw new Error("no such request: " + id);
    req.pageCount = pageCount;
    req.feeCents = computeFee(pageCount, press);
  }

  addExemption(id: string, code: string): void {
    const req = this.items.get(id);
    if (!req) throw new Error("no such request: " + id);
    if (!req.exemptions.includes(code)) {
      req.exemptions.push(code);
    }
  }

  deny(id: string): RecordsRequest {
    const req = this.items.get(id);
    if (!req) throw new Error("no such request: " + id);
    if (req.exemptions.length === 0) {
      throw new Error("a denial needs at least one exemption code");
    }
    req.status = "denied";
    return req;
  }

  overdue(now: Date = new Date()): RecordsRequest[] {
    const result: RecordsRequest[] = [];
    for (const req of this.items.values()) {
      if (req.status !== "fulfilled" && req.status !== "denied" && req.dueAt < now) {
        result.push(req);
      }
    }
    return result.sort((a, b) => a.dueAt.getTime() - b.dueAt.getTime());
  }

  receipt(id: string): string {
    const req = this.items.get(id);
    if (!req) throw new Error("no such request: " + id);
    const lines: string[] = [];
    lines.push("Halvern County Archive - request " + req.id);
    lines.push("Requester: " + req.requester + " <" + req.email + ">");
    lines.push("Received: " + req.receivedAt.toISOString().slice(0, 10));
    lines.push("Due: " + req.dueAt.toISOString().slice(0, 10));
    lines.push("Status: " + req.status);
    if (req.pageCount > 0) {
      const dollars = (req.feeCents / 100).toFixed(2);
      lines.push("Pages located: " + req.pageCount + ", fee: $" + dollars);
    }
    if (req.exemptions.length > 0) {
      lines.push("Exemptions applied: " + req.exemptions.join(", "));
    }
    return lines.join("\n");
  }

  waitingTimeDays(id: string, now: Date = new Date()): number {
    const req = this.items.get(id);
    if (!req) throw new Error("no such request: " + id);
    const ms = now.getTime() - req.receivedAt.getTime();
    return Math.floor(ms / (1000 * 60 * 60 * 24));
  }

  summary(): Record<RequestStatus, number> {
    const counts: Record<RequestStatus, number> = {
      received: 0,
      searching: 0,
      review: 0,
      fulfilled: 0,
      denied: 0,
    };
    for (const req of this.items.values()) {
      counts[req.status]++;
    }
    return counts;
  }
}
```

Two things I already know bother me. The fee for a requester who asks for exactly 26 pages came out wrong in a spreadsheet check last week, and the due date for requests that arrive on a Friday afternoon seems to land on the wrong day. I would like to know whether those are real bugs or whether I am misreading the code.

This module schedules which trams leave the Eastgate depot each morning and which bay each one is parked in overnight. I need a thorough code review (correctness, edge cases, style, anything risky) and then a complete set of unit tests written with pytest.

```python
"""depot.py - morning dispatch planning for the Eastgate tram depot."""

from dataclasses import dataclass, field
from datetime import time, timedelta, datetime
from typing import Dict, List, Optional

MAINTENANCE_LIMIT_KM = 12000
MAX_BAY_CAPACITY = 2


@dataclass
class Tram:
    number: int
    model: str
    km_since_service: int
    fault_codes: List[str] = field(default_factory=list)
    bay: Optional[str] = None

    def needs_service(self) -> bool:
        return self.km_since_service >= MAINTENANCE_LIMIT_KM

    def is_roadworthy(self) -> bool:
        if self.needs_service():
            return False
        return not any(code.startswith("B") for code in self.fault_codes)


@dataclass
class Departure:
    line: str
    scheduled: time
    tram: Optional[Tram] = None


class Depot:
    def __init__(self, bays: Dict[str, int]):
        # bays maps a bay name to its capacity
        self.bays = bays
        self.trams: Dict[int, Tram] = {}

    def add_tram(self, tram: Tram) -> None:
        if tram.number in self.trams:
            raise ValueError("tram already registered")
        self.trams[tram.number] = tram

    def park(self, number: int, bay: str) -> None:
        tram = self.trams[number]
        occupied = [t for t in self.trams.values() if t.bay == bay]
        capacity = self.bays.get(bay, MAX_BAY_CAPACITY)
        if len(occupied) > capacity:
            raise RuntimeError("bay full: " + bay)
        tram.bay = bay

    def roadworthy_trams(self) -> List[Tram]:
        return sorted(
            [t for t in self.trams.values() if t.is_roadworthy()],
            key=lambda t: t.km_since_service,
        )

    def plan_morning(self, departures: List[Departure]) -> List[Departure]:
        available = self.roadworthy_trams()
        ordered = sorted(departures, key=lambda d: d.scheduled)
        for dep in ordered:
            if not available:
                break
            dep.tram = available.pop()
        return ordered

    def unstaffed(self, departures: List[Departure]) -> List[Departure]:
        return [d for d in departures if d.tram is None]


def assign_night_bays(depot: Depot, preferred: Dict[str, str]) -> Dict[int, str]:
    """Give every tram a bay for the night.

    preferred maps a model name to the bay that has the right overhead
    charging gear for it. Trams whose preferred bay is full go to the
    first bay with space.
    """
    result: Dict[int, str] = {}
    for number in sorted(depot.trams):
        tram = depot.trams[number]
        wanted = preferred.get(tram.model)
        placed = False
        if wanted is not None:
            try:
                depot.park(number, wanted)
                placed = True
            except RuntimeError:
                placed = False
        if not placed:
            for bay in depot.bays:
                try:
                    depot.park(number, bay)
                    placed = True
                    break
                except RuntimeError:
                    continue
        if not placed:
            result[number] = "UNPLACED"
        else:
            result[number] = tram.bay
    return result


def load_fault_log(lines: List[str], depot: Depot) -> int:
    """Read lines of the form 'tram,code' and attach codes to trams.

    Returns the number of lines that could not be applied.
    """
    skipped = 0
    for line in lines:
        parts = line.strip().split(",")
        if len(parts) != 2:
            skipped += 1
            continue
        number, code = parts
        tram = depot.trams.get(int(number))
        if tram is None:
            skipped += 1
            continue
        tram.fault_codes.append(code)
    return skipped


def service_forecast(depot: Depot, daily_km: int) -> Dict[int, int]:
    """Days until each tram reaches the service limit at a given daily distance."""
    forecast: Dict[int, int] = {}
    for number, tram in depot.trams.items():
        remaining = MAINTENANCE_LIMIT_KM - tram.km_since_service
        forecast[number] = remaining // daily_km
    return forecast


def minutes_late(scheduled: time, actual: time) -> int:
    base = datetime(2026, 1, 1)
    s = datetime.combine(base, scheduled)
    a = datetime.combine(base, actual)
    delta = a - s
    return int(delta.total_seconds() / 60)


def report(depot: Depot, departures: List[Departure]) -> str:
    lines = []
    for dep in depot.plan_morning(departures):
        if dep.tram is None:
            lines.append(f"{dep.scheduled:%H:%M} line {dep.line}: NO TRAM")
        else:
            lines.append(
                f"{dep.scheduled:%H:%M} line {dep.line}: tram {dep.tram.number}"
                f" ({dep.tram.model}, {dep.tram.km_since_service} km)"
            )
    missing = depot.unstaffed(departures)
    if missing:
        lines.append(f"{len(missing)} departures without a tram")
    return "\n".join(lines)
```

Some background so you know what the dispatchers expect. Trams with fault codes starting with "B" have a brake problem and must never leave the depot; other fault codes (for example "D" for doors) are tolerated for a day. Trams with the fewest kilometres since service are supposed to go out on the earliest departures, because the early lines are the busiest. A bay should never hold more trams than its capacity. Last Tuesday the plan put the tram with the highest mileage on the 05:10 departure, which was the opposite of what we wanted, and one night bay 4 ended up with three trams in it. I would also like your opinion on whether the lateness helper does what its name suggests when a tram leaves after midnight.

This is the quoting package for our solar installation company, written by a contractor who has moved on. I need you to explain what each part does, review it for bugs and design problems, and write table-driven tests for the functions that matter most.

```go
// Package quote calculates system size, price and payback for a rooftop solar installation.
package quote

import (
	"errors"
	"fmt"
	"math"
	"sort"
)

const (
	PanelWatts       = 410
	PanelAreaM2      = 1.95
	InstallBaseCost  = 1800.0
	PanelCost        = 215.0
	InverterCostPerK = 140.0
	TariffPerKWh     = 0.31
	ExportPerKWh     = 0.07
	SelfUseShare     = 0.45
)

// Roof describes one plane of a roof.
type Roof struct {
	Name        string
	AreaM2      float64
	TiltDegrees float64
	Azimuth     float64 // degrees from north, 180 is due south
	ShadingPct  float64
}

// Quote is the result of a calculation.
type Quote struct {
	Panels       int
	SystemKW     float64
	AnnualKWh    float64
	TotalCost    float64
	AnnualSaving float64
	PaybackYears float64
}

var ErrNoRoof = errors.New("no usable roof area")

// usableArea returns the area that can take panels, leaving a margin around the edges.
func usableArea(r Roof) float64 {
	if r.AreaM2 <= 0 {
		return 0
	}
	return r.AreaM2 * 0.8
}

// orientationFactor reduces yield for roofs that do not face south.
func orientationFactor(azimuth float64) float64 {
	diff := math.Abs(azimuth - 180)
	if diff > 180 {
		diff = 360 - diff
	}
	switch {
	case diff <= 30:
		return 1.0
	case diff <= 60:
		return 0.9
	case diff <= 90:
		return 0.78
	default:
		return 0.6
	}
}

// tiltFactor reduces yield for very flat or very steep roofs.
func tiltFactor(tilt float64) float64 {
	if tilt >= 25 && tilt <= 45 {
		return 1.0
	}
	if tilt < 25 {
		return 0.95 - (25-tilt)*0.004
	}
	return 0.97 - (tilt-45)*0.006
}

// RoofYield returns the annual kWh produced per installed kW on a roof.
func RoofYield(r Roof, sunHours float64) float64 {
	base := sunHours * 365 * 0.82
	y := base * orientationFactor(r.Azimuth) * tiltFactor(r.TiltDegrees)
	y = y * (1 - r.ShadingPct/100)
	return y
}

// PanelsFor returns how many panels fit on a roof.
func PanelsFor(r Roof) int {
	return int(usableArea(r) / PanelAreaM2)
}

// Build prices a system that uses the best roofs first, up to maxPanels panels in total.
func Build(roofs []Roof, sunHours float64, maxPanels int) (Quote, error) {
	if len(roofs) == 0 {
		return Quote{}, ErrNoRoof
	}
	ranked := make([]Roof, len(roofs))
	copy(ranked, roofs)
	sort.Slice(ranked, func(i, j int) bool {
		return RoofYield(ranked[i], sunHours) > RoofYield(ranked[j], sunHours)
	})

	remaining := maxPanels
	var panels int
	var annual float64
	for _, r := range ranked {
		if remaining <= 0 {
			break
		}
		n := PanelsFor(r)
		if n > remaining {
			n = remaining
		}
		kw := float64(n*PanelWatts) / 1000
		annual += kw * RoofYield(r, sunHours)
		panels += n
		remaining -= n
	}
	if panels == 0 {
		return Quote{}, ErrNoRoof
	}

	kw := float64(panels*PanelWatts) / 1000
	cost := InstallBaseCost + float64(panels)*PanelCost + kw*1000*InverterCostPerK/1000
	used := annual * SelfUseShare
	exported := annual - used
	saving := used*TariffPerKWh + exported*ExportPerKWh

	q := Quote{
		Panels:       panels,
		SystemKW:     kw,
		AnnualKWh:    annual,
		TotalCost:    cost,
		AnnualSaving: saving,
		PaybackYears: cost / saving,
	}
	return q, nil
}

// Summary formats a quote for the customer letter.
func (q Quote) Summary() string {
	return fmt.Sprintf("%d panels (%.2f kW), about %.0f kWh a year, price %.2f, saving %.2f a year, payback %.1f years",
		q.Panels, q.SystemKW, q.AnnualKWh, q.TotalCost, q.AnnualSaving, q.PaybackYears)
}

// LifetimeSaving estimates the total saving over the given number of years, allowing
// for a fixed yearly loss of panel output.
func (q Quote) LifetimeSaving(years int, degradationPct float64) float64 {
	total := 0.0
	factor := 1.0
	for y := 0; y < years; y++ {
		total += q.AnnualSaving * factor
		factor *= 1 - degradationPct/100
	}
	return total - q.TotalCost
}

// BestRoof returns the name of the roof with the highest yield per installed kW.
func BestRoof(roofs []Roof, sunHours float64) (string, error) {
	if len(roofs) == 0 {
		return "", ErrNoRoof
	}
	best := roofs[0]
	for _, r := range roofs[1:] {
		if RoofYield(r, sunHours) > RoofYield(best, sunHours) {
			best = r
		}
	}
	return best.Name, nil
}

// Discount applies a percentage discount between 0 and 100 to the total cost.
func (q *Quote) Discount(pct float64) error {
	if pct < 0 || pct > 100 {
		return fmt.Errorf("invalid discount %.1f", pct)
	}
	q.TotalCost = q.TotalCost * (1 - pct/100)
	q.PaybackYears = q.TotalCost / q.AnnualSaving
	return nil
}
```

A few facts about how it is used. Customers' roofs usually have one to three planes. The sun-hours value comes from a regional table and is typically between 2.8 and 4.2. Last month a customer with a north-facing roof was quoted a payback of 9 years, which our sales manager says is impossible, and a quote for a very small roof came back with a payback of "+Inf".

